pub fn get (&self, i: usize) -> Option<bool> {
        if i >= self.nbits {
            None
        } else {
            let w = i / B::bits();
            let b = i % B::bits();
            let flag = B::one() << b;
            Some((self.storage[w] & flag) != B::zero())
        }
    }

