        assert!(i < self.nbits, "index out of bounds");
        let w = i / B::bits();
        let b = i % B::bits();
        let flag = B::one() << b;
        if x {
            self.storage[w] = self.storage[w] | flag;
        } else {
            self.storage[w] = self.storage[w] & !flag;
        }
    }

